package org.marketreview.nativeapp;
import org.json.*;
import java.util.*;
import java.util.regex.Pattern;
/** Deterministic local evidence projection. No lookups, quote imports, AI, or account changes. */
final class ResearchCompanies {
 static final String[] STAGES={"materials","equipment","components","manufacturing","applications","unknown"};
 static final String[] LABELS={"原材料与耗材","生产与检测设备","核心器件与零部件","制造、封装与集成","下游应用","环节待核验"};
 static void need(boolean ok,String why){if(!ok)throw new IllegalArgumentException(why);}
 static String stageLabel(String k){int i=Arrays.asList(STAGES).indexOf(k);return i<0?LABELS[5]:LABELS[i];}
 static boolean identity(String id){return id.matches("SH:stock:(60|68|90)[0-9]{4}|SZ:stock:(00|20|30)[0-9]{4}|BJ:stock:(4[0-9]|8[0-9]|92)[0-9]{4}");}
 static void validateMetadata(JSONObject r)throws JSONException{
  if(r.has("product"))need(r.opt("product") instanceof String&&r.getString("product").length()<=300,"产品字段必须为300字以内文字");if(!r.has("company")||r.isNull("company"))return;JSONObject c=r.optJSONObject("company");need(c!=null,"公司字段需为对象");need(!c.optString("name").trim().isEmpty()&&c.optString("name").length()<=200,"公司名需为1至200字");String id=c.optString("instrumentId");need(id.isEmpty()||identity(id),"证券身份需明确市场/股票/六位代码，且与市场代码范围匹配");
  if(!id.isEmpty()){String q=c.optString("identityQuote"),code=id.substring(id.lastIndexOf(':')+1);need(!c.optString("identityDocumentId").isEmpty()&&!q.trim().isEmpty()&&q.length()<=2000,"绑定证券需原文身份依据");need(q.contains(c.getString("name"))&&Pattern.compile("(?<![0-9])"+code+"(?![0-9])").matcher(q).find(),"身份引文需包含该公司名与独立证券代码");String marker=id.startsWith("SH:")?"上海证券交易所|上交所|SH:stock:"+code+"|sh"+code:id.startsWith("SZ:")?"深圳证券交易所|深交所|SZ:stock:"+code+"|sz"+code:"北京证券交易所|北交所|BJ:stock:"+code+"|bj"+code;need(Pattern.compile(marker).matcher(q).find(),"身份引文缺少对应市场依据，不按公司名或代码猜市场");}
 }
 static void validateReferences(JSONObject r,Map<String,String> docs)throws JSONException{validateMetadata(r);JSONObject c=r.optJSONObject("company");if(c==null||c.optString("instrumentId").isEmpty())return;String id=c.optString("identityDocumentId");need(docs.containsKey(id)&&docs.get(id).contains(c.optString("identityQuote")),"公司身份引文必须逐字匹配已有原文；未改写原文");}
 static String statusLabel(String k){switch(k){case "manuallyVerified":return "人工已核验";case "disputed":return "有争议";case "legacyVerified":return "旧人工核验·当前原文未复核";case "matched":return "旧资料匹配·待核验";case "legacy":return "旧版本·待复核";default:return "待核验";}}
 static JSONObject project(String topic,JSONArray relations,JSONArray docs,JSONArray reports)throws JSONException{
  Map<String,JSONObject> byDoc=new HashMap<>();for(int i=0;i<docs.length();i++){JSONObject d=docs.getJSONObject(i);byDoc.put(d.optString("id"),d);}JSONArray rows=new JSONArray(),warnings=new JSONArray();
  for(int i=0;i<relations.length();i++){JSONObject r=relations.getJSONObject(i);if(!topic.equals(r.optString("topicId")))continue;JSONObject d=byDoc.getOrDefault(r.optString("documentId"),new JSONObject()),c=r.optJSONObject("company"),row=new JSONObject(r.toString());if(c==null)c=new JSONObject();row.put("key",r.optString("id")).put("relationId",r.optString("id")).put("companyName",c.optString("name","公司未绑定")).put("instrumentId",c.optString("instrumentId")).put("status",r.optString("verification").equals("manuallyVerified")?"manuallyVerified":"candidate").put("readOnly",false).put("bodyAvailable",!r.optString("quote").isEmpty()&&d.optString("text").contains(r.optString("quote"))).put("originalDocument",d).put("originalRecord",new JSONObject(r.toString())).put("evidenceRefs",new JSONArray().put(new JSONObject().put("documentId",d.optString("id")).put("quote",r.optString("quote")).put("url",d.optString("sourceUrl"))));rows.put(row);}
  String oldTopic=topic.startsWith("legacy-topic:")?topic.substring(13):"";JSONObject latest=new JSONObject(),versionDoc=new JSONObject();int sequence=-1;if(!oldTopic.isEmpty())for(int i=0;i<reports.length();i++){JSONObject d=reports.getJSONObject(i);if(!d.optString("legacySource").equals("industry_research_versions"))continue;JSONObject p;try{p=new JSONObject(d.optString("text"));}catch(JSONException e){warnings.put("归档版本JSON无法读取："+d.optString("id"));continue;}if(oldTopic.equals(p.optString("topicId"))&&p.optInt("sequence",-1)>sequence){sequence=p.getInt("sequence");latest=p;versionDoc=d;}}
  JSONArray archived=latest.optJSONArray("relations");if(archived!=null)for(int i=0;i<archived.length();i++){JSONObject r=archived.getJSONObject(i),c=r.optJSONObject("company"),row=new JSONObject(r.toString());if(c==null)c=new JSONObject();String s=r.optString("status");row.put("key",versionDoc.optString("id")+":"+i).put("relationId",r.optString("id")).put("topicId",topic).put("companyName",c.optString("name","公司未绑定")).put("instrumentId","").put("status",s.equals("verified")?"legacyVerified":s.equals("disputed")?"disputed":s.equals("confirmed")?"matched":"legacy").put("verification","unverified").put("readOnly",true).put("bodyAvailable",false).put("originalRecord",new JSONObject(r.toString())).put("originalDocument",versionDoc).put("versionSequence",sequence).put("observedAt",latest.optString("createdAt"));rows.put(row);}
  Map<String,Set<String>> polarities=new HashMap<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String key=r.optString("companyName")+"|"+r.optString("product")+"|"+r.optString("stage");polarities.computeIfAbsent(key,k->new HashSet<>()).add(r.optString("polarity","supports"));}for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);Set<String> ps=polarities.get(r.optString("companyName")+"|"+r.optString("product")+"|"+r.optString("stage"));if(!r.optString("companyName").equals("公司未绑定")&&ps.contains("supports")&&ps.contains("contradicts"))r.put("status","disputed");if(!Arrays.asList(STAGES).contains(r.optString("stage")))r.put("stage","unknown");}
  JSONArray lanes=new JSONArray();for(String stage:STAGES){JSONArray keys=new JSONArray();for(int i=0;i<rows.length();i++)if(stage.equals(rows.getJSONObject(i).optString("stage")))keys.put(rows.getJSONObject(i).optString("key"));lanes.put(new JSONObject().put("stage",stage).put("label",stageLabel(stage)).put("keys",keys));}return new JSONObject().put("schema","native-research-companies/v1").put("topicId",topic).put("rows",rows).put("lanes",lanes).put("warnings",warnings).put("boundary","环节归属图；没有公司间供货边或营收推断。归档引用不等于当前原文复核。");
 }
}
